import { z } from "zod";
import { couponKind, foodType, staffRole, storeSettings } from "./schemas";

/* Inputs for the admin portal. Money is paise; slugs are generated by the API when omitted. */

const name = z.string().trim().min(1, "Enter a name").max(120);
const slug = z
  .string()
  .trim()
  .toLowerCase()
  .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, "Use lowercase letters, numbers and dashes")
  .max(120);
const imageUrl = z
  .string()
  .trim()
  .max(500)
  .refine((u) => u.startsWith("/") || u.startsWith("https://"), "Use an uploaded photo")
  .nullable();

export const categoryInput = z.object({ name, slug: slug.optional(), imageUrl: imageUrl.optional(), active: z.boolean().optional() });
export const categoryPatch = categoryInput.partial().omit({ slug: true });
export type CategoryInput = z.infer<typeof categoryInput>;
export type CategoryPatch = z.infer<typeof categoryPatch>;

export const sectionInput = z.object({ categoryId: z.string().min(1), name, slug: slug.optional() });
export const sectionPatch = z.object({ name: name.optional(), categoryId: z.string().min(1).optional() });
export type SectionInput = z.infer<typeof sectionInput>;
export type SectionPatch = z.infer<typeof sectionPatch>;

export const itemInput = z.object({
  sectionId: z.string().min(1),
  name,
  slug: slug.optional(),
  description: z.string().trim().max(400).default(""),
  foodType,
  pricePaise: z.number().int().min(100, "Price must be at least ₹1").max(10_000_00, "That price looks too high"),
  quantityLabel: z.string().trim().max(40).nullable().optional(),
  note: z.string().trim().max(200).nullable().optional(),
  isBestseller: z.boolean().default(false),
  isAvailable: z.boolean().default(true),
  imageUrl: imageUrl.optional(),
});
export const itemPatch = itemInput.partial().omit({ slug: true });
export type ItemInput = z.infer<typeof itemInput>;
export type ItemPatch = z.infer<typeof itemPatch>;

export const availabilityInput = z.object({ isAvailable: z.boolean() });

/** New order of ids (slugs) within one parent. */
export const reorderInput = z.object({ ids: z.array(z.string().min(1)).min(1).max(300) });
export type ReorderInput = z.infer<typeof reorderInput>;

export const storePatch = storeSettings.partial().refine((p) => Object.keys(p).length > 0, "Nothing to update");
export type StorePatch = z.infer<typeof storePatch>;

export const uploadRequest = z.object({
  contentType: z.enum(["image/jpeg", "image/png", "image/webp"]),
  size: z.number().int().positive().max(5 * 1024 * 1024, "Photos must be under 5 MB"),
});
export type UploadRequest = z.infer<typeof uploadRequest>;
export type UploadTicket = { path: string; token: string; publicUrl: string; bucket: string };

const optionalDate = z.string().datetime({ offset: true }).nullable().optional();
export const couponInput = z
  .object({
    code: z
      .string()
      .trim()
      .toUpperCase()
      .regex(/^[A-Z0-9]{3,20}$/, "3 to 20 letters or numbers"),
    description: z.string().trim().min(3, "Describe the offer").max(120),
    kind: couponKind,
    value: z.number().int().positive(),
    minOrderPaise: z.number().int().min(0).default(0),
    maxDiscountPaise: z.number().int().positive().nullable().optional(),
    startsAt: optionalDate,
    endsAt: optionalDate,
    usageLimit: z.number().int().positive().nullable().optional(),
    perUserLimit: z.number().int().positive().nullable().optional(),
    active: z.boolean().default(true),
  })
  .refine((c) => c.kind !== "percent" || c.value <= 10_000, { message: "Percent can't be over 100%", path: ["value"] })
  .refine((c) => !c.startsAt || !c.endsAt || c.startsAt < c.endsAt, { message: "End must be after start", path: ["endsAt"] });
export const couponPatch = z.object({
  description: z.string().trim().min(3).max(120).optional(),
  active: z.boolean().optional(),
  endsAt: optionalDate,
  usageLimit: z.number().int().positive().nullable().optional(),
});
export type CouponInput = z.infer<typeof couponInput>;
export type CouponPatch = z.infer<typeof couponPatch>;

export type AdminCoupon = Omit<CouponInput, "startsAt" | "endsAt"> & {
  id: string;
  startsAt: string | null;
  endsAt: string | null;
  used: number;
  createdAt: string;
};

export const staffInvite = z.object({
  email: z.string().trim().toLowerCase().email("Enter a valid email"),
  name: z.string().trim().min(1, "Enter their name").max(80),
  role: staffRole,
});
export const staffPatch = z.object({ role: staffRole.optional(), active: z.boolean().optional() });
export type StaffInvite = z.infer<typeof staffInvite>;
export type StaffPatch = z.infer<typeof staffPatch>;
export type StaffMember = { userId: string; email: string | null; name: string | null; role: z.infer<typeof staffRole>; active: boolean; createdAt: string };

export type AuditEntry = { id: string; at: string; actorEmail: string | null; action: string; entity: string; entityId: string | null; before: unknown; after: unknown };

/** Admin view of the menu: includes sold-out items and hidden categories. */
export type AdminMenuItem = {
  id: string;
  name: string;
  description: string;
  foodType: z.infer<typeof foodType>;
  pricePaise: number;
  quantityLabel: string | null;
  note: string | null;
  isBestseller: boolean;
  isAvailable: boolean;
  imageUrl: string | null;
  sort: number;
};
export type AdminMenuSection = { id: string; name: string; sort: number; items: AdminMenuItem[] };
export type AdminMenuCategory = { id: string; name: string; sort: number; active: boolean; imageUrl: string | null; sections: AdminMenuSection[] };

/** "Chilli Cheese Toast" -> "chilli-cheese-toast" */
export const slugify = (s: string) =>
  s
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^\w\s-]/g, "")
    .trim()
    .replace(/[\s_-]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80) || "item";
